import type { ErrorRequestHandler } from 'express';
import { getErrorMessage } from '../utils/errors';

// Currently A Placeholder Error Handler Generated By Claude

// Safety net for errors no controller caught, including malformed JSON bodies
// rejected by express.json(). Responds with JSON instead of Express's HTML page.
// Controllers should still handle their own expected errors.
export const errorHandler: ErrorRequestHandler = (error, req, res, next) => {
  
  // Excluded from coverage: only reachable if a response was already partly
  // sent before the error, which is out of scope for our expectations.
  /* v8 ignore start -- @preserve */
  if (res.headersSent) {
    next(error);
    return;
  }
  /* v8 ignore stop -- @preserve */

  // express.json() marks bad request bodies with a 4xx status; keep it.
  const status: unknown = error?.status;

  // The false branch of this covers purely defensive code
  /* v8 ignore else -- @preserve */ 
  if (typeof status === 'number' && status >= 400 && status < 500) {
    res.status(status).json({ error: 'Invalid request' });
    return;
  }

  // Excluded from coverage: only reachable by unexpected errors no controller
  // caught. This is purely defensive code.
  /* v8 ignore start -- @preserve */
  console.error('Unhandled error:', getErrorMessage(error));
  res.status(500).json({ error: 'Internal server error' });
  /* v8 ignore stop -- @preserve */
};
